"""Finding the stretches of opening hours that nobody covers."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import merge_spans


def _check_inside(worked: Iterable[Span], opening: Span) -> None:
    for span in worked:
        if span.start < opening.start or span.end > opening.end:
            raise ValueError(f"{format_span(span)} is outside opening hours")


def uncovered_spans(worked: Iterable[Span], opening: Span) -> List[Span]:
    """The parts of opening that no worked span covers, in order."""
    cursor = opening.start
    result = []
    edges = [(item.start, item.end) for item in merge_spans(worked)]
    for begin, stop in edges + [(opening.end, opening.end)]:
        if begin > cursor:
            result.append(Span(cursor, begin))
        cursor = max(cursor, stop)
    return result


def find_gaps(worked: Iterable[Span], opening: Span) -> List[str]:
    """One label per uncovered stretch, such as 'gap 12:00-13:00 (60 min)'."""
    worked = list(worked)
    _check_inside(worked, opening)
    return [
        f"gap {format_span(gap)} ({gap.minutes} min)"
        for gap in uncovered_spans(worked, opening)
    ]

